const mult = (arr) => {
    let res = 0;

    for (let i = 0; i < arr.length; i++) {
        res += i * arr[i];
    }

    return res;
};

const rotate = (arr) => {
    const res = arr.slice(1);
    res.push(arr[0]);
    return res;
};

