    const n = nums.length;

    let total = nums.reduce((acc, el) => acc + el, 0);
    let curr = nums.reduce((acc, el, i) => acc + (i * el), 0);

    let res = curr;

    for (let i = 0; i < n; i++) {
        curr = curr - total + n * nums[i];
        res = Math.max(res, curr);
    }

    return res;
};

