    const n = nums.length;

    let total = 0;
    let mult = 0;

    for (let i = 0; i < n; i++) {
        total += nums[i];
        mult += i * nums[i];
    }

    let res = mult;

    for (let i = 1; i < n; i++) {
        mult += n * nums[i - 1] - total;

        if (mult > res) {
            res = mult;
        }
    }

